def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    remaining = 100 - n
    if remaining == 1:
        return 'D'
    if remaining == 2:
        if opp_def == 0:
            return 'D'
        return 'C'

    if n >= 10 and opp_def > 0.7 * n:
        return 'D'

    if opp_def == 0:
        if my_def > 0:
            if history[-1][0] == 'D':
                return 'C'
            else:
                if remaining <= 5:
                    return 'D'
                if rng.random() < 0.8:
                    return 'D'
                return 'C'
        else:
            if n >= 10 and n % 20 == 0:
                return 'D'
            return 'C'

    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'

    if n >= 2:
        if opp_def >= 3 and opp_def >= n // 2:
            return 'D'

    my_last, opp_last = history[-1]
    if opp_last == 'D' and my_last == 'D':
        if opp_def >= 3 and opp_def >= n // 2:
            return 'D'
        return 'C'

    return 'C'
